make sure when this is called that the input is an object called formData. That formData object will have the following as it's JSON object {
  "device": "aws-lab-junos",
  "target_version": "22.4R2.8",
  "image_path": "/var/tmp/junos-install-vsrx3-x86-64-22.4R2.8.tgz",
  "image_sha256": "8d486921598bb89afd3ab54dcf8fa7cb80423c3977ddaa86dd15e84f13d465b2"
}

incoming.template:
{#-
  NetBox -> IAG5 Inventory Template — JUNOS / Hybrid
  Filters: active Junos devices with an IP.
Adjust as desired, make sure to set passwords with SECRETS
-#}

{% set junos_slugs = ['juniper-junos', 'vsrx'] %}

{% set credentials = {'user': 'itential', 'password': 'password'} %}

{% set device_overrides = {} %}

{% set netmiko_opts = {
    'banner_timeout':        60,
    'session_timeout':       300,
    'read_timeout_override': 600,
    'conn_timeout':          60,
    'global_delay_factor':   3,
    'enable_fast_mode':      false
} %}

{% set netconf_opts = {
    'port':               830,
    'timeout':            30,
    'lock_timeout':       60,
    'lock_poll_interval': 2,
    'command_timeout': 600,
    'config_format':  'set'
} %}

[
{%- set ns = namespace(first=true) %}
{%- for device in body.results %}

  {%- set nb_platform = (device.platform.slug if device.platform else device.device_type.slug) or '' %}

  {%- if device.primary_ip4 %}
    {%- set ip_address = device.primary_ip4.address.split('/')[0] %}
  {%- elif device.config_context and device.config_context.ipAddress %}
    {%- set ip_address = device.config_context.ipAddress %}
  {%- else %}
    {%- set ip_address = '' %}
  {%- endif %}

  {%- set creds = device_overrides.get(device.name, credentials) %}

  {%- set driver_options = {'netmiko': netmiko_opts, 'netconf': netconf_opts} %}

  {%- if ip_address and nb_platform in junos_slugs and device.status and device.status.value == 'active' %}
{{ "," if not ns.first else "" }}
{%- set ns.first = false %}
  {
    "name": "{{ device.name }}",
    "attributes": {
      "itential_host":           "{{ ip_address }}",
      "itential_port":           22,
      "itential_driver":         "netmiko",
      "itential_platform":       "juniper_junos",
      "itential_user":           "{{ creds.user }}",
      "itential_password":       "{{ creds.password }}",
      "itential_driver_options": {{ driver_options | tojson }}
    },
    "tags": [
      "{{ (device.role.slug if device.role else 'unknown') }}",
      "{{ (device.site.slug if device.site else 'unknown') }}",
      "{{ (device.status.value if device.status else 'unknown') }}",
      "driver:netmiko",
      "platform:juniper_junos",
      "transport:cli+netconf"
    ]
  }
  {%- endif %}
{%- endfor %}
]
